import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;

    static long modPow(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int n = Integer.parseInt(br.readLine());
        long[][] p = new long[6][6];
        for (int i = 0; i < 6; i++) {
            Arrays.fill(p[i], 1);
        }

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                double val = Double.parseDouble(st.nextToken());
                long valLong = Math.round(val * modPow(100, (int)(MOD - 2)));
                p[i][j] = valLong % MOD;
            }
        }

        for (int i = n; i < 6; i++) {
            for (int j = n; j < 6; j++) {
                p[i][j] = 1;
            }
        }

        List<int[]> edges = new ArrayList<>();
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 3; j++) {
                edges.add(new int[]{i, j});
            }
        }

        long[] F = new long[1 << 20];
        int[] mask_indices = new int[1 << 18];
        Arrays.fill(mask_indices, 0);
        int idx = 0;

        // Generate all triplets of vertices
        for (int i = 0; i < 6; i++) {
            for (int j = i + 1; j < 6; j++) {
                for (int k = j + 1; k < 6; k++) {
                    int[] v = {i, j, k};
                    do {
                        int msk1 = (1 << (v[0] * 3)) ^ (1 << (v[1] * 3 + 1)) ^ (1 << (v[2] * 3 + 2));
                        for (int mask = 0; mask < (1 << 18); mask++) {
                            if ((mask & msk1) == msk1) {
                                mask_indices[mask] = idx;
                            }
                        }
                    } while (nextPermutation(v));
                    idx++;
                }
            }
        }

        // Precompute products for all masks
        for (int mask = 0; mask < (1 << 18); mask++) {
            long prod = 1;
            for (int i = 0; i < 18; i++) {
                if (((mask >> i) & 1) == 1) {
                    int[] edge = edges.get(i);
                    prod = (prod * p[edge[0]][edge[1]]) % MOD;
                } else {
                    int[] edge = edges.get(i);
                    prod = (prod * (MOD + 1 - p[edge[0]][edge[1]])) % MOD;
                }
            }
            F[mask_indices[mask]] = (F[mask_indices[mask]] + prod) % MOD;
        }

        // Fast Walsh–Hadamard transform
        for (int i = 0; i < 20; i++) {
            for (int mask = 0; mask < (1 << 20); mask++) {
                if (((mask >> i) & 1) == 1) {
                    F[mask] = (F[mask] + F[mask ^ (1 << i)]) % MOD;
                }
            }
        }

        List<int[]> edges2 = new ArrayList<>();
        for (int i = 0; i < 6; i++) {
            for (int j = 3; j < 6; j++) {
                edges2.add(new int[]{i, j});
            }
        }

        long total = 0;
        for (int mask = 0; mask < (1 << 18); mask++) {
            long prod = 1;
            for (int i = 0; i < 18; i++) {
                if (((mask >> i) & 1) == 1) {
                    int[] edge = edges2.get(i);
                    prod = (prod * p[edge[0]][edge[1]]) % MOD;
                } else {
                    int[] edge = edges2.get(i);
                    prod = (prod * (MOD + 1 - p[edge[0]][edge[1]])) % MOD;
                }
            }
            long val = (prod * ((1 - F[((1 << 20) - 1) ^ mask_indices[mask]] + MOD) % MOD)) % MOD;
            total = (total + val) % MOD;
        }

        System.out.println(total);
    }

    static boolean nextPermutation(int[] arr) {
        int i = arr.length - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;
        }
        int j = arr.length - 1;
        while (arr[j] <= arr[i]) {
            j--;
        }
        swap(arr, i, j);
        reverse(arr, i + 1, arr.length - 1);
        return true;
    }

    static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    static void reverse(int[] arr, int start, int end) {
        while (start < end) {
            swap(arr, start++, end--);
        }
    }
}
